import json, random, time, statistics
import numpy as np
import torch
from skyjo import game, models, predictor, mcts, batches, train, objectives

torch.set_num_threads(1)
torch.manual_seed(0)
model=models.build({'embedding_dimensions':16,'global_state_embedding_dimensions':32,'num_heads':2},players=2,device='cpu')
inference=predictor.LocalPredictor(model,64)
rng=random.Random(120)
state=game.start_round(game.new(players=2,rng=rng),rng=rng)
states=[]
for i in range(1000):
    if game.get_round_over(state): state=game.start_round(game.new(players=2,rng=rng),rng=rng)
    states.append(state)
    state=game.apply_action(state,int(np.flatnonzero(game.actions(state))[i%int(game.actions(state).sum())]),rng=rng)
inputs=batches.states_to_batch(states[:64])
inputs=batches.TrainingBatch(inputs.spatial_inputs,inputs.non_spatial_inputs,inputs.action_masks,{'value':np.full((64,2),.5,dtype=np.float32),'policy':inputs.action_masks/inputs.action_masks.sum(axis=1,keepdims=True)})
optimizer=torch.optim.Adam(model.parameters(),lr=.001)
def engine():
    for i,s in enumerate(states): game.apply_action(s,int(np.flatnonzero(game.actions(s))[i%int(game.actions(s).sum())]),rng=random.Random(i))
def infer():
    for _ in range(20): inference.predict_many(states[:64])
def search():
    for i in range(10):
        random.seed(i); np.random.seed(i)
        mcts.run_mcts(states[50+i],inference,32)
def optimize():
    for _ in range(20): train.train_step(model,inputs,objectives.configured_loss,optimizer)
results={}
for name,fn in [('transitions_1000',engine),('inference_1280',infer),('search_10x32',search),('optimizer_20x64',optimize)]:
    fn(); timings=[]
    for _ in range(3):
        started=time.perf_counter(); fn(); timings.append(time.perf_counter()-started)
    results[name]={'median_seconds':statistics.median(timings),'seconds':timings}
print(json.dumps(results,indent=2))
